// Spec 602 · the library on meeting night, an original illustration. Story art: it shows the room and the board,
// not which plan is right. In chapter 4 the three plan cards pin up one by one; in the ending, new pencil draws
// itself on the old map (a line, a question mark, a small reed). Everything settles within a few seconds;
// reduced motion shows the finished picture.
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lantern=(x,d)=>`<g class="a4m-lantern" style="--d:${d}s"><path d="M${x} 18 v14" stroke="#6b5a45" stroke-width="2"/><rect x="${x-9}" y="32" width="18" height="22" rx="4" fill="#f3d27a" stroke="#8a6a3a" stroke-width="2"/><circle class="a4m-glow" cx="${x}" cy="43" r="20" fill="#f6dc8a" opacity=".35"/></g>`;
const shelf=y=>`<path d="M14 ${y} H626" stroke="#b79c78" stroke-width="3"/>${Array.from({length:30},(_,i)=>{const x=20+i*20.5,h=14+((i*7)%9);return `<rect x="${x}" y="${y-h}" width="${8+(i%3)*2}" height="${h}" fill="${['#9b6b5a','#5e7f8c','#8a9a5b','#c49a5a','#7a6a9a'][i%5]}" opacity=".75"/>`;}).join('')}`;
// The three plan cards: a wall of stones, reeds in water, half of each. Pictures only; the text is on the page.
// The outer group places the card; the inner group is what CSS rotates and pins, so the two transforms never clash.
const card=(x,rot,d,art)=>`<g transform="translate(${x} 196)"><g class="a4m-card" style="--d:${d}s;--r:${rot}deg"><rect x="-38" y="-30" width="76" height="60" rx="3" fill="#fffdf6" stroke="#b9a27e" stroke-width="2"/><circle cx="0" cy="-27" r="4" fill="#b4483c"/>${art}</g></g>`;
const wallArt=`<g stroke="#7d6b55" stroke-width="2" fill="#cdbb9c"><rect x="-26" y="-6" width="16" height="10"/><rect x="-8" y="-6" width="16" height="10"/><rect x="10" y="-6" width="16" height="10"/><rect x="-17" y="6" width="16" height="10"/><rect x="1" y="6" width="16" height="10"/></g><path d="M-30 20 h60" stroke="#78b7cf" stroke-width="3"/>`;
const spongeArt=`<path d="M-30 14 q30 10 60 0" stroke="#78b7cf" stroke-width="3" fill="none"/>${[-18,-6,6,18].map(x=>`<path d="M${x} 14 q2 -14 ${x>0?4:-4} -28" stroke="#5f7d3f" stroke-width="2.5" fill="none"/><path d="M${x+(x>0?4:-4)} -14 q1 -6 0 -10" stroke="#7a5a32" stroke-width="4" stroke-linecap="round"/>`).join('')}`;
const someArt=`<g stroke="#7d6b55" stroke-width="2" fill="#cdbb9c"><rect x="-28" y="-2" width="14" height="9"/><rect x="-28" y="8" width="14" height="9"/></g><path d="M-10 18 q20 6 38 -2" stroke="#78b7cf" stroke-width="3" fill="none"/>${[6,16].map(x=>`<path d="M${x} 16 q2 -12 3 -24" stroke="#5f7d3f" stroke-width="2.5" fill="none"/>`).join('')}`;
const heads=Array.from({length:11},(_,i)=>{const x=40+i*56,y=278+(i%2)*6,c=['#8a6a52','#c48f6a','#6d4f3d','#d4a67e','#a6785a'][i%5];return `<g><circle cx="${x}" cy="${y-18}" r="13" fill="${c}"/><path d="M${x-20} ${y+14} q20 -26 40 0" fill="${['#5e7f8c','#9b6b5a','#7a8a5a','#7a6a9a','#b07a4a'][i%5]}"/></g>`;}).join('');
const pencil=`<g class="a4m-pencil" fill="none" stroke="#3a3a3a" stroke-width="2.4" stroke-linecap="round"><path pathLength="1" class="a4m-stroke" style="--d:.2s" d="M220 120 C 262 100 304 132 352 110"/><path pathLength="1" class="a4m-stroke" style="--d:1s" d="M436 90 q0 -10 9 -10 q9 0 9 9 q0 7 -9 11 v7 M445 115 v2"/><path pathLength="1" class="a4m-stroke" style="--d:1.8s" d="M300 146 q2 -16 4 -26 M304 120 q1 -5 0 -9 M296 146 q-4 -12 -8 -18"/></g>`;
// The library window shows the season the act ended in (spec 120 §6: an ending wears its season).
const windowArt=season=>{
 const frame=`<rect x="20" y="20" width="62" height="46" rx="3" fill="#cfe2ea" stroke="#8a6a3a" stroke-width="3"/><path d="M51 20 v46 M20 43 h62" stroke="#8a6a3a" stroke-width="2"/>`;
 const motif={spring:`<circle cx="34" cy="31" r="3" fill="#f2b8c6"/><circle cx="40" cy="35" r="2.5" fill="#f2b8c6"/><circle cx="64" cy="53" r="3" fill="#f2b8c6"/><path d="M28 60 q8 -8 16 -4" stroke="#6f8d4a" stroke-width="2" fill="none"/>`,summer:`<circle cx="66" cy="31" r="7" fill="#f3d27a"/><path d="M24 60 h24" stroke="#6f8d4a" stroke-width="3"/>`,autumn:`<path d="M30 28 l4 4 -4 4 -4 -4z" fill="#c9773a"/><path d="M60 48 l4 4 -4 4 -4 -4z" fill="#b4483c"/><path d="M42 54 l3 3 -3 3 -3 -3z" fill="#d49a3a"/>`,winter:`<path d="M24 62 q14 -6 28 0 q14 6 28 0 v4 h-56z" fill="#ffffff"/><path d="M34 30 l4 4 M38 30 l-4 4 M64 48 l4 4 M68 48 l-4 4" stroke="#ffffff" stroke-width="2"/>`}[season]||'';
 return `<g data-a4-season="${season||'none'}">${frame}${motif}</g>`;
};

export function meetingScene(label,caption,{penciled=false,season=null}={}){
 return `<figure class="a4-meeting" data-a4-meeting data-penciled="${penciled}"><svg viewBox="0 0 640 300" role="img" aria-label="${esc(label)}"><rect width="640" height="300" fill="#efe6d4"/><rect y="250" width="640" height="50" fill="#d9c7a6"/>${shelf(84)}${shelf(124)}${shelf(164)}${penciled?windowArt(season):''}${lantern(130,0)}${lantern(250,.3)}${lantern(390,.6)}${lantern(560,.9)}<g data-a4-board><rect x="96" y="62" width="448" height="176" rx="4" fill="#7a5c3e"/><rect x="106" y="70" width="428" height="160" fill="#f6efdc"/><path d="M118 92 C 170 116 214 86 262 116 C 302 140 352 124 398 146 C 440 160 478 128 522 150" stroke="#78b7cf" stroke-width="4" fill="none"/><ellipse cx="300" cy="128" rx="70" ry="24" fill="#9cbf86" opacity=".45"/><path d="M118 160 h50 M460 86 h50" stroke="#b9a27e" stroke-width="2"/></g>${penciled?pencil:''}<path d="M140 238 l-14 14 M500 238 l14 14" stroke="#6b4f35" stroke-width="5"/>${card(186,-4,.2,wallArt)}${card(320,2,.6,spongeArt)}${card(454,-2,1,someArt)}${heads}</svg><figcaption>${esc(caption)}</figcaption></figure>`;
}
